// Exact translations take priority. The trie handles composed logs and numeric messages
// in one pass; it never reads or observes the document.
let phraseTrie=null;
function buildPhraseTrie(){const root=new Map();for(const[key,value]of Object.entries(UI_EN)){if(!key||key===value||/^[<>"]/.test(key))continue;let node=root;for(const c of key){if(!node.has(c))node.set(c,new Map());node=node.get(c)}node.translation=value;node.source=key}return root}
function wordCharacter(c){return !!c&&/[\p{L}\p{N}_]/u.test(c)}
function translateComposed(value){phraseTrie ||= buildPhraseTrie();let result='',offset=0;while(offset<value.length){let node=phraseTrie,index=offset,best=null,end=offset;while(index<value.length&&node.has(value[index])){node=node.get(value[index++]);if(node.translation!==undefined&&!(wordCharacter(node.source[0])&&wordCharacter(value[offset-1]))&&!(wordCharacter(node.source.at(-1))&&wordCharacter(value[index]))){best=node.translation;end=index}}if(best!==null){result+=best;offset=end}else result+=value[offset++]}return result}
export function uiText(text){if(uiLanguage!=='en')return text;const value=String(text),key=value.trim();if(Object.prototype.hasOwnProperty.call(UI_EN,key))return value.replace(key,()=>UI_EN[key]);const count=key.match(/^(\d+) de (\d+) respuestas correctas$/);if(count)return value.replace(key,()=>count[1]+' of '+count[2]+' correct answers');const transit=key.match(/^(✓ Coincidencia|✕ Modelo por ajustar): caída ([\d.]+)% frente a ([\d.]+)%\. Al aumentar el radio, aumenta el área que tapa la luz\.$/);if(transit)return value.replace(key,()=>UI_EN[transit[1]]+': dip '+transit[2]+'% versus '+transit[3]+'%. Increasing the radius increases the area blocking light.');const result=baseUiText(value);return translateComposed(result)}
function decodeHtmlText(value){const named={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:'\u00a0'};return value.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi,(all,key)=>{if(key[0]!=='#')return named[key.toLowerCase()]||all;const number=key[1].toLowerCase()==='x'?parseInt(key.slice(2),16):parseInt(key.slice(1),10);return number>0&&number<=0x10ffff?String.fromCodePoint(number):all})}
function escapeHtmlText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
export function translateHtml(html){if(uiLanguage!=='en')return html;return String(html).replace(/(<style\b[^>]*>[\s\S]*?<\/style>|<[^>]+>)|([^<]+)/gi,(all,tag,text)=>{if(tag){if(/^<style\b/i.test(tag))return tag;return tag.replace(/\blang=(["'])es\1/gi,'lang="en"').replace(/(\b(?:aria-label|aria-valuetext|title|alt|placeholder)\s*=\s*)(["'])(.*?)\2/gi,(_,prefix,quote,value)=>prefix+quote+escapeHtmlText(uiText(decodeHtmlText(value)))+quote)}return escapeHtmlText(uiText(decodeHtmlText(text)))})}

export function refreshLanguage(){
 document.documentElement.lang=uiLanguage;
 for(const[id,label]of Object.entries({continueDock:'Continuar después de leer el resultado',journeyProgress:'Tu progreso en la misión',closeModal:'Cerrar'})){const node=document.getElementById(id);if(node)node.setAttribute('aria-label',uiText(label))}
 const labels={sources:'Fuentes NASA ↗',skipCinema:'Continuar →',learnTopHelp:'¿Cómo se juega?'};
 for(const[id,text]of Object.entries(labels)){const node=document.getElementById(id);if(node)node.textContent=uiText(text)}
 const button=$('#language');if(button){button.textContent='ES / EN';button.setAttribute('aria-pressed',String(uiLanguage==='en'));button.setAttribute('aria-label',uiLanguage==='en'?'Switch the entire game to Spanish':'Cambiar todo el juego a inglés');button.setAttribute('title',uiLanguage==='en'?'Switch the entire game to Spanish':'Cambiar todo el juego a inglés')}
 const live=document.querySelector('.header-actions .live');if(live)live.textContent=uiText('● SISTEMAS ACTIVOS');
 const subtitle=document.querySelector('.brand small');if(subtitle)subtitle.textContent=uiText('UNA MISIÓN. CADA DECISIÓN CUENTA.');
 const audio=$('#audio');if(audio)audio.textContent=uiText(`Sonido: ${sound.audioOn?'activado':'apagado'}`);
 if(game.cinema){$('#cinemaTitle').textContent=uiText(game.cinema.title);$('#cinemaText').textContent=uiText(game.cinema.text);$('#cinemaTag').textContent=uiText(game.cinema.type==='death'?'ÚLTIMA TELEMETRÍA':game.cinema.type==='success'?'CIENCIA · EQUIPO · REGRESO':'SECUENCIA DE MISIÓN')}
 if(notify.lastMessage&&$('#notice').style.display!=='none')$('#notice').textContent=uiText(notify.lastMessage);
 updateMusicButton();
}
export function setUiLanguage(value){uiLanguage=value==='en'?'en':'es';rerenderForLanguage();refreshLanguage()}
export function initLanguage(){const button=$('#language');if(button)button.onclick=()=>setUiLanguage(uiLanguage==='es'?'en':'es');refreshLanguage()}

